extern const char str_010dcb40[116] = "See m_snapGain. The angular velocity calculated from the snapGain is clamped to " "this limit before being applied.\000\000\000";
extern const unsigned char zero_010dcbb4[4] = {0};
extern const char str_010dcbb8[112] = "See m_snapGain. The linear velocity calculated from the snapGain is clamped to t" "his limit before being applied.";
extern const char str_010dcc28[316] = "This gain allows for precise matching between keyframes and the current position" ". It works like the m_positionGain: it calculates an optimal deltaVelocity, scal" "es it by m_snapGain, clips it against m_snapMaxXXXVelocity and scales it down if" " the implied positional difference is larger than m_snapMaxXXXXDistance.\000\000" "\000";
extern const unsigned char zero_010dcd64[4] = {0};
