extern const unsigned char zero_010dd124[4] = {0};
extern const char str_010dd128[288] = "This gain dampens the velocities of the bodies. The current velocity of the body" " is scaled by this parameter on every frame before the controller is applied. It" " is applied every step and is generally more aggressive than standard linear or " "angular damping. A value of 0 means no damping.";
